# Glass Forehearth & IS Machine ST Generator
# Cyber-Physical Systems & Automation Architecture (V7 Max-Persona)

import os
import sys

def build_iec_code():
    lines = []
    def emit(text=""):
        lines.append(text)

    # -------------------------------------------------------------------------
    # 1. HEADER & SYSTEM SPECIFICATION
    # -------------------------------------------------------------------------
    emit("FUNCTION_BLOCK FB_Glass_IS_Machine_ForehearthGobShear_LehrAnneal")
    emit("(*")
    emit(" ====================================================================================================")
    emit("  LUMINA CYBER-PHYSICAL AUTOMATION ENGINE - ULTRA-RIGOROUS SYNTHETIC DATASET V7 MAX-PERSONA")
    emit("  DOMAIN: GLASS, CERAMICS & CONTAINER MANUFACTURING (TIER 1 PRIORITY MASS PRODUCTION SECTOR)")
    emit("  SYSTEM: HIGH-SPEED GLASS FOREHEARTH & 12-SECTION QUAD-GOB INDIVIDUAL SECTION (IS) MACHINE")
    emit("  INTEGRATED SUBSYSTEMS:")
    emit("    1. FOREHEARTH OXY-FUEL MULTI-ZONE THERMAL CONDITIONING & EQUALIZATION (1150 DEG C)")
    emit("    2. GOB FEEDER DUAL SERVO PLUNGER RECIPROCATION & TUBE ROTATION HOMOGENIZATION")
    emit("    3. HIGH-SPEED DUAL PNEUMATIC/SERVO OPPOSED SHEAR CUT-OFF & LUBRICOOLANT SPRAY")
    emit("    4. DUAL HIGH-SPEED OPTICAL VISION PYROMETRY (GOB MASS, DROP VELOCITY, L/D ASPECT RATIO)")
    emit("    5. REVOLVING SCOOP GOB DISTRIBUTOR & DELIVERY CHUTE / TROUGH RUNNER COLLATOR")
    emit("    6. 12-SECTION QUAD-GOB ELECTRONIC TIMING DRUM (360 DEGREE ROTARY CYCLE WITH 30 DEGREE STAGGER)")
    emit("    7. BLANK SIDE: PNEUMATIC FUNNEL, SETTLE BLOW, BAFFLE SEAL & SERVO/COUNTER-BLOW PARISON FORMING")
    emit("    8. SERVO INVERT MECHANISM WITH 180 DEGREE HIGH-SPEED PARISON SWING & NECK RING RELEASE")
    emit("    9. BLOW SIDE: BLOWHEAD SEAL, FINAL BLOW AIR EXPANSION, VACUUM ASSIST & INTERNAL CHILL")
    emit("   10. SERVO TAKE-OUT MECHANISM WITH 180 DEGREE TRANSFER TO PNEUMATIC DEADPLATE COOLING")
    emit("   11. PNEUMATIC/SERVO SWEEPOUT MECHANISM & HIGH-SPEED MACHINE CONVEYOR TRANSLATION")
    emit("   12. 3-AXIS SERVO LEHR STACKER PUSHBAR & CROSS-CONVEYOR TRANSFER DRIVE")
    emit("   13. CONTINUOUS ANNEALING LEHR MULTI-ZONE TUNNEL GRADIENT TEMPERATURE PROFILE & STRESS RELAXATION")
    emit("   14. DEFECTIVE GOB/WARE HIGH-SPEED CULLET DIVERT CHUTE & BASEMENT SCRAPER CONVEYOR RECYCLING")
    emit("  REAL-TIME SAMPLE TIME: Ts = 5.0 ms (FAST DETERMINISTIC CYBER-PHYSICAL PLC LOOP)")
    emit("  NOMINAL CAPACITY     : 480 TO 720 CONTAINERS/MINUTE (QUAD-GOB 12-SECTION AT 10 TO 15 CYCLES/MIN)")
    emit("  SAFETY INTEGRITY     : IEC 61508 SIL-3 / IEC 62061 SILCL-3 / ISO 13849-1 PL e ARCHITECTURE")
    emit("  ALARM MANAGEMENT     : ISA-18.2 / ANSI/ISA-18.2-2016 MULTI-TIER PRIORITY ESCALATION")
    emit(" ====================================================================================================")
    emit("*)")
    emit("")

    # -------------------------------------------------------------------------
    # 2. VAR_INPUT BLOCK
    # -------------------------------------------------------------------------
    emit("VAR_INPUT")
    emit("    (* ========================================================================================= *)")
    emit("    (* SYSTEM MASTER CONTROL & SAFETY PERMISSIVES                                                *)")
    emit("    (* ========================================================================================= *)")
    emit("    bEnableSystem                   : BOOL := FALSE;    (* Master System Enable Permissive Command *)")
    emit("    bEmergencyStopOk                : BOOL := TRUE;     (* Dual-Channel Safety Relay E-Stop Permissive [Active High OK] *)")
    emit("    bSafetyGateInterlocksOk         : BOOL := TRUE;     (* 12-Section Machine Enclosure Safety Fence Interlock [Active High OK] *)")
    emit("    bAcknowledgeFaults              : BOOL := FALSE;    (* Operator Master Alarm & Trip Reset Acknowledge Pulse *)")
    emit("    bAutoModeActive                 : BOOL := FALSE;    (* Automatic Production Synchronous Mode Selection *)")
    emit("    bManualCulletDivertCmd          : BOOL := FALSE;    (* Manual Operator Override to Divert All Gobs to Cullet Chute *)")
    emit("")
    emit("    (* ========================================================================================= *)")
    emit("    (* FOREHEARTH THERMAL CONDITIONING SENSORS (TRI-LEVEL Pt/Rh TYPE R/S THERMOCOUPLES)         *)")
    emit("    (* ========================================================================================= *)")
    emit("    rForehearthZone1Temp_A_degC     : REAL := 1220.0;   (* Forehearth Zone 1 Cooling Thermocouple Channel A [deg C] *)")
    emit("    rForehearthZone1Temp_B_degC     : REAL := 1220.0;   (* Forehearth Zone 1 Cooling Thermocouple Channel B [deg C] *)")
    emit("    rForehearthZone1Temp_C_degC     : REAL := 1220.0;   (* Forehearth Zone 1 Cooling Thermocouple Channel C [deg C] *)")
    emit("    rForehearthZone2Temp_A_degC     : REAL := 1180.0;   (* Forehearth Zone 2 Conditioning Thermocouple Channel A [deg C] *)")
    emit("    rForehearthZone2Temp_B_degC     : REAL := 1180.0;   (* Forehearth Zone 2 Conditioning Thermocouple Channel B [deg C] *)")
    emit("    rForehearthZone2Temp_C_degC     : REAL := 1180.0;   (* Forehearth Zone 2 Conditioning Thermocouple Channel C [deg C] *)")
    emit("    rForehearthSpoutTemp_A_degC     : REAL := 1150.0;   (* Spout / Feeder Bowl Glass Melt Thermocouple Channel A [deg C] *)")
    emit("    rForehearthSpoutTemp_B_degC     : REAL := 1150.0;   (* Spout / Feeder Bowl Glass Melt Thermocouple Channel B [deg C] *)")
    emit("    rForehearthSpoutTemp_C_degC     : REAL := 1150.0;   (* Spout / Feeder Bowl Glass Melt Thermocouple Channel C [deg C] *)")
    emit("    rForehearthGasPressure_bar      : REAL := 2.50;     (* Oxy-Fuel Combustion Gas Supply Manifold Pressure [bar] *)")
    emit("    rForehearthAirGasRatio          : REAL := 10.2;     (* Combustion Air to Fuel Stoichiometric Ratio Target [-] *)")
    emit("")
    emit("    (* ========================================================================================= *)")
    emit("    (* FEEDER PLUNGER & TUBE SERVO MECHANISM SENSORS                                             *)")
    emit("    (* ========================================================================================= *)")
    emit("    rPlungerStrokeSP_mm             : REAL := 52.0;     (* Servo Feeder Plunger Downward Stroke Setpoint [mm] *)")
    emit("    rPlungerSpeedSP_gpm             : REAL := 120.0;    (* Plunger Reciprocating Cycle Speed Setpoint [gobs/min] *)")
    emit("    rPlungerActualPos_mm            : REAL := 52.0;     (* Plunger Servo Resolver Actual Linear Position Feedback [mm] *)")
    emit("    rTubeRotationSpeed_rpm          : REAL := 4.5;      (* Ceramic Revolving Tube Rotational Speed Feedback [rpm] *)")
    emit("    rTubeHeightAdjust_mm            : REAL := 15.0;     (* Revolving Tube Vertical Gap Clearance Above Orifice [mm] *)")
    emit("")
    emit("    (* ========================================================================================= *)")
    emit("    (* DUAL OPTICAL VISION PYROMETERS & HIGH-SPEED GOB MASS SCANNERS                            *)")
    emit("    (* ========================================================================================= *)")
    emit("    rGobOpticalTemp_A_degC          : REAL := 1148.0;   (* Optical Infrared Radiation Pyrometer Channel A [deg C] *)")
    emit("    rGobOpticalTemp_B_degC          : REAL := 1148.0;   (* Optical Infrared Radiation Pyrometer Channel B [deg C] *)")
    emit("    rGobOpticalTemp_C_degC          : REAL := 1148.0;   (* Optical Infrared Radiation Pyrometer Channel C [deg C] *)")
    emit("    rGobMassMeasured_A_g            : REAL := 325.0;    (* High-Speed Laser Scan Gob Mass Verification Channel A [g] *)")
    emit("    rGobMassMeasured_B_g            : REAL := 325.0;    (* High-Speed Laser Scan Gob Mass Verification Channel B [g] *)")
    emit("    rGobMassMeasured_C_g            : REAL := 325.0;    (* High-Speed Laser Scan Gob Mass Verification Channel C [g] *)")
    emit("    rGobMassTarget_g                : REAL := 325.0;    (* Nominal Container Target Gob Mass [g] *)")
    emit("    rGobLengthMeasured_mm           : REAL := 142.0;    (* Vision Line-Scan Gob Extrusion Length Feedback [mm] *)")
    emit("    rGobDiameterMeasured_mm         : REAL := 48.0;     (* Vision Line-Scan Gob Transverse Diameter Feedback [mm] *)")
    emit("    rGobDropVelocity_mms            : REAL := 2200.0;   (* Free-Fall Gob Drop Velocity at Delivery Chute Inlet [mm/s] *)")
    emit("")
    emit("    (* ========================================================================================= *)")
    emit("    (* PNEUMATIC / SERVO SHEAR CUT-OFF MECHANISM SENSORS                                         *)")
    emit("    (* ========================================================================================= *)")
    emit("    rShearVelocityActual_A_mms      : REAL := 1250.0;   (* Shear Blade Cutting Linear Speed Sensor A [mm/s] *)")
    emit("    rShearVelocityActual_B_mms      : REAL := 1250.0;   (* Shear Blade Cutting Linear Speed Sensor B [mm/s] *)")
    emit("    rShearVelocityActual_C_mms      : REAL := 1250.0;   (* Shear Blade Cutting Linear Speed Sensor C [mm/s] *)")
    emit("    rShearMechanismTension_bar      : REAL := 6.20;     (* Shear Mechanism Pneumatic Cushion Tension Pressure [bar] *)")
    emit("    rShearLubricoolantPress_bar     : REAL := 3.80;     (* Shear Blade Lubricoolant Water/Oil Emulsion Pressure [bar] *)")
    emit("    rShearBladeTemp_degC            : REAL := 85.0;     (* Shear Upper/Lower Carbide Blade Surface Temperature [deg C] *)")
    emit("")
    emit("    (* ========================================================================================= *)")
    emit("    (* 12-SECTION IS MACHINE MASTER ELECTRONIC TIMING DRUM & PNEUMATIC SENSORS                  *)")
    emit("    (* ========================================================================================= *)")
    emit("    rMasterTimingDrumAngle_deg      : REAL := 0.0;      (* Master Electronic Timing Drum Rotational Phase Angle [deg] *)")
    emit("    rBlankMoldCoolAirPress_A_bar    : REAL := 4.20;     (* Blank Mold High-Pressure Cooling Manifold Pressure A [bar] *)")
    emit("    rBlankMoldCoolAirPress_B_bar    : REAL := 4.20;     (* Blank Mold High-Pressure Cooling Manifold Pressure B [bar] *)")
    emit("    rBlankMoldCoolAirPress_C_bar    : REAL := 4.20;     (* Blank Mold High-Pressure Cooling Manifold Pressure C [bar] *)")
    emit("    rSettleBlowPress_A_bar          : REAL := 2.80;     (* Blank Side Settle Blow Header Pressure Sensor A [bar] *)")
    emit("    rSettleBlowPress_B_bar          : REAL := 2.80;     (* Blank Side Settle Blow Header Pressure Sensor B [bar] *)")
    emit("    rSettleBlowPress_C_bar          : REAL := 2.80;     (* Blank Side Settle Blow Header Pressure Sensor C [bar] *)")
    emit("    rCounterBlowPress_A_bar         : REAL := 2.40;     (* Blank Side Parison Counter Blow Pressure Sensor A [bar] *)")
    emit("    rCounterBlowPress_B_bar         : REAL := 2.40;     (* Blank Side Parison Counter Blow Pressure Sensor B [bar] *)")
    emit("    rCounterBlowPress_C_bar         : REAL := 2.40;     (* Blank Side Parison Counter Blow Pressure Sensor C [bar] *)")
    emit("    rFinalBlowPress_A_bar           : REAL := 3.20;     (* Blow Side Container Final Blow Pressure Sensor A [bar] *)")
    emit("    rFinalBlowPress_B_bar           : REAL := 3.20;     (* Blow Side Container Final Blow Pressure Sensor B [bar] *)")
    emit("    rFinalBlowPress_C_bar           : REAL := 3.20;     (* Blow Side Container Final Blow Pressure Sensor C [bar] *)")
    emit("    rBlowMoldVacuum_bar             : REAL := -0.65;    (* Blow Mold Cavity Evacuation Vacuum Assist Pressure [bar] *)")
    emit("    rDeadplateAirBlastPress_bar     : REAL := 2.10;     (* Take-Out Deadplate Base Quench Cooling Air Pressure [bar] *)")
    emit("")
    emit("    (* ========================================================================================= *)")
    emit("    (* SERVO MECHANISM RESOLVER ANGLE SENSORS (INVERT & TAKE-OUT ARMS)                          *)")
    emit("    (* ========================================================================================= *)")
    emit("    rInvertServoAngle_A_deg         : REAL := 0.0;      (* Section Servo Invert Arm Angular Position Sensor A [deg] *)")
    emit("    rInvertServoAngle_B_deg         : REAL := 0.0;      (* Section Servo Invert Arm Angular Position Sensor B [deg] *)")
    emit("    rInvertServoAngle_C_deg         : REAL := 0.0;      (* Section Servo Invert Arm Angular Position Sensor C [deg] *)")
    emit("    rTakeOutServoAngle_A_deg        : REAL := 0.0;      (* Section Servo Take-Out Arm Angular Position Sensor A [deg] *)")
    emit("    rTakeOutServoAngle_B_deg        : REAL := 0.0;      (* Section Servo Take-Out Arm Angular Position Sensor B [deg] *)")
    emit("    rTakeOutServoAngle_C_deg        : REAL := 0.0;      (* Section Servo Take-Out Arm Angular Position Sensor C [deg] *)")
    emit("    rMachineConveyorSpeed_mpm       : REAL := 42.0;     (* IS Machine High-Speed Silent Chain Conveyor Speed [m/min] *)")
    emit("")
    emit("    (* ========================================================================================= *)")
    emit("    (* CONTINUOUS ANNEALING LEHR MULTI-ZONE SENSORS & POLARIMETER STRESS                        *)")
    emit("    (* ========================================================================================= *)")
    emit("    rLehrZone1HeatingTemp_degC      : REAL := 555.0;    (* Lehr Tunnel Zone 1 Heating / Annealing Point Temp [deg C] *)")
    emit("    rLehrZone2SoakTemp_degC         : REAL := 545.0;    (* Lehr Tunnel Zone 2 Thermal Equalization Soak Temp [deg C] *)")
    emit("    rLehrZone3CoolTemp_degC         : REAL := 495.0;    (* Lehr Tunnel Zone 3 Controlled Strain Point Temp [deg C] *)")
    emit("    rLehrZone4DischargeTemp_degC    : REAL := 75.0;     (* Lehr Tunnel Zone 4 Forced Air Cold-End Discharge Temp [deg C] *)")
    emit("    rLehrBeltSpeed_mmin             : REAL := 1.25;     (* Lehr Continuous Stainless Steel Mesh Belt Speed [m/min] *)")
    emit("    rLehrStressPolarimeter_A_MPa    : REAL := 1.85;     (* In-Line Polarimeter Optical Residual Annealing Stress A [MPa] *)")
    emit("    rLehrStressPolarimeter_B_MPa    : REAL := 1.85;     (* In-Line Polarimeter Optical Residual Annealing Stress B [MPa] *)")
    emit("    rLehrStressPolarimeter_C_MPa    : REAL := 1.85;     (* In-Line Polarimeter Optical Residual Annealing Stress C [MPa] *)")
    emit("    bCulletConveyorRunning          : BOOL := TRUE;     (* Basement Water Quench Cullet Scraper Running Feedback *)")
    emit("    rCulletWaterQuenchFlow_m3h      : REAL := 18.5;     (* Basement Cullet Chute Water Quench Flush Flow [m3/h] *)")
    emit("END_VAR")
    emit("")

    # -------------------------------------------------------------------------
    # 3. VAR_OUTPUT BLOCK
    # -------------------------------------------------------------------------
    emit("VAR_OUTPUT")
    emit("    (* ========================================================================================= *)")
    emit("    (* MACHINE MASTER STATUS & BIT-PACKED DIAGNOSTIC REGISTERS                                  *)")
    emit("    (* ========================================================================================= *)")
    emit("    bSystemReady                    : BOOL := FALSE;    (* IS Machine & Forehearth Ready for Production *)")
    emit("    bSystemActive                   : BOOL := FALSE;    (* Automated Synchronous Container Forming Active *)")
    emit("    bSafetyTripActive               : BOOL := FALSE;    (* Master SIL-3 Safety Emergency Trip Interlock Latched *)")
    emit("    bCulletDivertActive             : BOOL := FALSE;    (* High-Speed Gob Deflector Chute Actuated to Basement Cullet *)")
    emit("    bEmergencyShearLockOut          : BOOL := FALSE;    (* Pneumatic Emergency Shear Lock / Retract Solenoid Active *)")
    emit("    nFsmStateCurrent                : INT  := 0;        (* Current Operational Finite State Machine State Code *)")
    emit("    dwSystemStatusWord              : DWORD := 16#0000; (* Bit-Packed Operational Subsystem Status Register *)")
    emit("    dwAlarmHierarchyWord1           : DWORD := 16#0000; (* ISA-18.2 Priority 1 & 2 Latched Trip/Alarm Bitmask *)")
    emit("    dwAlarmHierarchyWord2           : DWORD := 16#0000; (* ISA-18.2 Priority 3 Warning & Advisory Alarm Bitmask *)")
    emit("    dwTmrIntegrityStatus            : DWORD := 16#0000; (* 2oo3 TMR Channel Degradation & Discrepancy Bitmask *)")
    emit("")
    emit("    (* ========================================================================================= *)")
    emit("    (* VOTED CYBER-PHYSICAL PROCESS VARIABLES (2oo3 TMR RESULTS)                                 *)")
    emit("    (* ========================================================================================= *)")
    emit("    rVotedForehearthSpoutTemp_degC  : REAL := 1150.0;   (* 2oo3 Voted Forehearth Spout Melt Temperature [deg C] *)")
    emit("    rVotedGobOpticalTemp_degC       : REAL := 1148.0;   (* 2oo3 Voted Optical Pyrometer Gob Temperature [deg C] *)")
    emit("    rVotedGobMass_g                 : REAL := 325.0;    (* 2oo3 Voted High-Speed Laser Scan Gob Mass [g] *)")
    emit("    rVotedShearVelocity_mms         : REAL := 1250.0;   (* 2oo3 Voted Shear Cutting Linear Speed [mm/s] *)")
    emit("    rVotedBlankCoolAirPress_bar     : REAL := 4.20;     (* 2oo3 Voted Blank Mold Cooling Air Pressure [bar] *)")
    emit("    rVotedSettleBlowPress_bar       : REAL := 2.80;     (* 2oo3 Voted Settle Blow Header Pressure [bar] *)")
    emit("    rVotedFinalBlowPress_bar        : REAL := 3.20;     (* 2oo3 Voted Final Blow Header Pressure [bar] *)")
    emit("    rVotedInvertServoAngle_deg      : REAL := 0.0;      (* 2oo3 Voted Section Servo Invert Arm Angle [deg] *)")
    emit("    rVotedTakeOutServoAngle_deg     : REAL := 0.0;      (* 2oo3 Voted Section Servo Take-Out Arm Angle [deg] *)")
    emit("    rVotedLehrStress_MPa            : REAL := 1.85;     (* 2oo3 Voted Lehr Polarimeter Residual Thermal Stress [MPa] *)")
    emit("")
    emit("    (* ========================================================================================= *)")
    emit("    (* ACTUATOR COMMANDS & CLOSED-LOOP CONTROL OUTPUTS                                          *)")
    emit("    (* ========================================================================================= *)")
    emit("    rForehearthZone3BurnerCmd_pct   : REAL := 45.0;     (* Forehearth Zone 3 Oxy-Fuel Burner Fuel Throttle Cmd [%] *)")
    emit("    rPlungerStrokeTrimCmd_mm        : REAL := 0.0;      (* Feeder Plunger Stroke Length Closed-Loop Trim Cmd [mm] *)")
    emit("    rShearVelocityThrottleCmd_pct   : REAL := 82.5;     (* Pneumatic/Servo Shear Drive Velocity Throttle Cmd [%] *)")
    emit("    rBlankMoldCoolAirValve_pct      : REAL := 65.0;     (* Blank Mold Cooling Proportional Air Valve Position [%] *)")
    emit("    rFinalBlowPressureSP_bar        : REAL := 3.20;     (* Section Final Blow Proportional Pressure Regulator SP [bar] *)")
    emit("    rBlowMoldCoolAirDamper_pct      : REAL := 55.0;     (* Blow Mold External Axial Cooling Air Damper Position [%] *)")
    emit("    rTakeOutServoTorqueCmd_Nm       : REAL := 0.0;      (* Servo Take-Out Drive Torque Feedforward / Trim Cmd [Nm] *)")
    emit("    rLehrAnnealHeatingPower_pct     : REAL := 48.0;     (* Lehr Zone 1 Electric Heating / Radiant Burner Modulation [%] *)")
    emit("    bShearCutSolenoid               : BOOL := FALSE;    (* High-Speed Pneumatic Shear Cut Pulse Actuation Command *)")
    emit("    bShearSprayLubricationCmd       : BOOL := FALSE;    (* High-Speed Shear Lubricoolant Spray Pulse Command *)")
    emit("    bGobDistributorIndexCmd         : BOOL := FALSE;    (* Gob Distributor Scoop Index Step Command *)")
    emit("    bSectionSettleBlowValve         : BOOL := FALSE;    (* Active Section Blank Settle Blow Solenoid Energize Cmd *)")
    emit("    bSectionCounterBlowValve        : BOOL := FALSE;    (* Active Section Blank Counter Blow Solenoid Energize Cmd *)")
    emit("    bSectionInvertMotionPermissive  : BOOL := FALSE;    (* Active Section Servo Invert Swing Motion Permissive *)")
    emit("    bSectionFinalBlowValve          : BOOL := FALSE;    (* Active Section Blowhead Final Blow Solenoid Energize Cmd *)")
    emit("    bSectionTakeOutMotionPermissive : BOOL := FALSE;    (* Active Section Servo Take-Out Swing Motion Permissive *)")
    emit("    bDeadplateBaseAirBlastValve     : BOOL := FALSE;    (* Take-Out Deadplate Bottom Quench Air Blast Solenoid Cmd *)")
    emit("    bSweepoutCylinderCmd            : BOOL := FALSE;    (* Pneumatic Sweepout Arm Advance to Machine Conveyor Cmd *)")
    emit("    bStackerPushbarAdvanceCmd       : BOOL := FALSE;    (* 3-Axis Servo Lehr Stacker Pushbar Loading Sweep Cmd *)")
    emit("    rCalculatedGlassViscosity_dPas  : REAL := 1000.0;   (* Cyber-Physical Observer Vogel-Fulcher Glass Viscosity [dPa.s] *)")
    emit("    rMpcQuadraticCostJ              : REAL := 0.0;      (* Receding-Horizon MPC Total Quadratic Cost Functional Value *)")
    emit("    nMpcSolverIterations            : INT  := 0;        (* Number of Projected Gradient Descent Iterations Completed *)")
    emit("END_VAR")
    emit("")

    return "\n".join(lines)

if __name__ == "__main__":
    print("Test build header & IO...")
    res = build_iec_code()
    print("Length:", len(res))
